body {
    font-family: Arial, sans-serif;
    background-color: #f4f4f9;
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
    margin: 0;
}

div {
    background: white;
    padding: 30px;
    border-radius: 8px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    width: 300px;
}

input[type="text"], input[type="password"] {
    width: 100%;
    padding: 8px;
    margin-top: 5px;
    margin-bottom: 15px;
    border: 1px solid #ccc;
    border-radius: 4px;
    box-sizing: border-box;
}

input[type="submit"], a {
    display: block;
    width: 100%;
    padding: 10px;
    background-color: #007bff;
    color: white;
    border: none;
    border-radius: 4px;
    text-align: center;
    text-decoration: none;
    cursor: pointer;
    box-sizing: border-box;
}

input[type="submit"]:hover, a:hover {
    background-color: #0056b3;
}

/* Dashboard Styles Below */
.dashboard-box {
    width: 500px;
}

.scroll-box {
    max-height: 300px;
    overflow-y: scroll;
    margin: 20px 0;
    padding-right: 10px;
    text-align: left;
    border-top: 1px solid #eee;
    border-bottom: 1px solid #eee;
    width: 100% !important;   
    box-sizing: border-box;
}


.order-row {
    padding: 10px 0;
    border-bottom: 1px solid #eee;
    font-size: 0.9em;
    color: #444;
}

.order-row strong {
    color: #007bff;
}

